package io.github.jhipster.sample.service;

import io.github.jhipster.sample.domain.Operation;
import io.github.jhipster.sample.repository.OperationRepository;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Service Implementation for managing {@link Operation}.
 */
@Service
@Transactional(readOnly = true)
public class OperationService {

    static final Duration RECENT_WINDOW = Duration.ofDays(30);

    private final OperationRepository operationRepository;

    private final Clock clock;

    public OperationService(OperationRepository operationRepository, Clock clock) {
        this.operationRepository = operationRepository;
        this.clock = clock;
    }

    /**
     * Get the operations whose date lies within the last 30 days, up to now.
     *
     * @return the list of operations, newest first.
     */
    public List<Operation> findRecentOperations() {
        Instant now = Instant.now(clock);
        return operationRepository.findAllWithEagerRelationshipsBetween(now.minus(RECENT_WINDOW), now);
    }
}
EOF
